/* Animated silk backdrop.
 *
 * The static JPEG in public/backdrop-silk.jpg is generated by the same maths.
 * This draws it live so the folds drift, and it is strictly an enhancement:
 * if anything here does not apply, the JPEG stays visible underneath and the
 * page looks exactly as it did before.
 *
 * The loop is seamless by construction rather than by cross-fading. The fold
 * field itself never moves; what advances is the phase of the ridge function
 * that carves creases into it, plus a warp offset that travels a circle. Both
 * are periodic, so at t = PERIOD every input is bit-identical to t = 0.
 *
 * Skipped entirely for prefers-reduced-motion, when the tab is hidden, and
 * when WebGL is unavailable.
 */
(function () {
  "use strict";

  var PERIOD = 24;          // seconds per loop
  var FPS = 30;             // a soft background does not need 60
  var SCALE = 0.55;         // render below CSS resolution; silk hides it

  var VERT =
    "attribute vec2 p;" +
    "void main(){gl_Position=vec4(p,0.,1.);}";

  var FRAG = [
    "precision highp float;",
    "uniform vec2 res;",
    "uniform float ang;",      // loop angle, 0..2PI
    "",
    "float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}",
    "",
    "float vnoise(vec2 p){",
    "  vec2 i=floor(p), f=fract(p);",
    "  vec2 u=f*f*(3.0-2.0*f);",             // smoothstep
    "  return mix(mix(hash(i),hash(i+vec2(1,0)),u.x),",
    "             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),u.x),u.y);",
    "}",
    "",
    "float fbm(vec2 p){",
    "  float v=0.0,a=1.0,t=0.0;",
    "  for(int i=0;i<4;i++){v+=a*vnoise(p);t+=a;a*=0.48;p*=2.0;}",
    "  return v/t;",
    "}",
    "",
    "void main(){",
    "  vec2 uv=gl_FragCoord.xy/res;",
    "  float aspect=res.x/max(res.y,1.0);",
    "  vec2 q=vec2(uv.x*aspect,uv.y);",
    "",
    "  // Anisotropic sampling: few cells across, more down, so structures",
    "  // stretch sideways into drawn folds instead of pooling into blobs.",
    "  vec2 s=vec2(q.x*2.2,q.y*5.0);",
    "",
    "  // Warp offset travels a circle, so it returns exactly to its start.",
    "  vec2 drift=vec2(cos(ang),sin(ang))*0.30;",
    "  vec2 w=vec2(fbm(s*0.7+drift),fbm(s*0.7+drift+vec2(5.2,1.3)));",
    "  vec2 sw=s+vec2((w.x-0.5)*1.10,(w.y-0.5)*2.60);",
    "  float field=fbm(sw);",
    "",
    "  // The creases. Advancing this phase is what makes the folds appear to",
    "  // stream across the cloth; 1-|sin| gives a crest rather than a hump.",
    "  float phase=field*6.6+q.x*1.1+q.y*0.5+ang;",
    "  float ridge=pow(1.0-abs(sin(phase)),1.35);",
    "",
    "  // Specular off the height-map gradient. The finite difference has to be",
    "  // divided by the sample distance to be a derivative; without that the",
    "  // term is ~300x too small and the folds all but vanish.",
    "  float e=0.004;",
    "  float fx=(fbm(sw+vec2(e,0.0))-fbm(sw-vec2(e,0.0)))/(2.0*e);",
    "  float fy=(fbm(sw+vec2(0.0,e))-fbm(sw-vec2(0.0,e)))/(2.0*e);",
    "  float spec=clamp(-fx*1.7-fy*0.8,0.0,1.0);",
    "  spec=pow(spec,0.85);",
    "",
    "  float lum=clamp(0.34*field+0.62*ridge+0.55*spec,0.0,1.0);",
    "  lum=pow(lum,0.92);",
    "",
    "  vec3 dark=vec3(5.0,14.0,36.0)/255.0;",
    "  vec3 mid=vec3(14.0,44.0,108.0)/255.0;",
    "  vec3 light=vec3(64.0,132.0,220.0)/255.0;",
    "  vec3 col=lum<0.5?mix(dark,mid,lum/0.5):mix(mid,light,(lum-0.5)/0.5);",
    "",
    "  vec2 v=(uv-0.5)*2.0;",
    "  col*=clamp(1.05-0.30*dot(v,v),0.0,1.2);",
    "",
    "  gl_FragColor=vec4(col,1.0);",
    "}"
  ].join("\n");

  function compile(gl, type, src) {
    var sh = gl.createShader(type);
    gl.shaderSource(sh, src);
    gl.compileShader(sh);
    if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) {
      gl.deleteShader(sh);
      return null;
    }
    return sh;
  }

  function start() {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

    var canvas = document.createElement("canvas");
    canvas.className = "silk-canvas";
    canvas.setAttribute("aria-hidden", "true");

    var gl = canvas.getContext("webgl", {
      alpha: false, antialias: false, depth: false,
      stencil: false, powerPreference: "low-power"
    }) || canvas.getContext("experimental-webgl");
    if (!gl) return;

    var vs = compile(gl, gl.VERTEX_SHADER, VERT);
    var fs = compile(gl, gl.FRAGMENT_SHADER, FRAG);
    if (!vs || !fs) return;

    var prog = gl.createProgram();
    gl.attachShader(prog, vs);
    gl.attachShader(prog, fs);
    gl.linkProgram(prog);
    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) return;
    gl.useProgram(prog);

    var buf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
    gl.bufferData(gl.ARRAY_BUFFER,
      new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    var loc = gl.getAttribLocation(prog, "p");
    gl.enableVertexAttribArray(loc);
    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);

    var uRes = gl.getUniformLocation(prog, "res");
    var uAng = gl.getUniformLocation(prog, "ang");

    // Only reveal the canvas once a frame is actually on it, so a failure
    // part-way through never shows a blank rectangle over the JPEG.
    var shown = false;
    document.body.appendChild(canvas);

    function resize() {
      var dpr = Math.min(window.devicePixelRatio || 1, 2);
      var w = Math.max(1, Math.round(window.innerWidth * dpr * SCALE));
      var h = Math.max(1, Math.round(window.innerHeight * dpr * SCALE));
      if (w === canvas.width && h === canvas.height) return;
      canvas.width = w;
      canvas.height = h;
      gl.viewport(0, 0, w, h);
      gl.uniform2f(uRes, w, h);
    }
    resize();

    var raf = 0, last = 0, t0 = null;
    var frameMs = 1000 / FPS;

    function frame(t) {
      raf = requestAnimationFrame(frame);
      if (t0 === null) t0 = t;
      if (t - last < frameMs) return;
      last = t;
      var loop = ((t - t0) / 1000 % PERIOD) / PERIOD;
      gl.uniform1f(uAng, loop * Math.PI * 2.0);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      if (!shown) { canvas.classList.add("is-on"); shown = true; }
    }
    raf = requestAnimationFrame(frame);

    var rt;
    window.addEventListener("resize", function () {
      clearTimeout(rt);
      rt = setTimeout(resize, 200);
    }, { passive: true });

    // Stop drawing entirely while the tab is in the background.
    document.addEventListener("visibilitychange", function () {
      if (document.hidden) {
        if (raf) { cancelAnimationFrame(raf); raf = 0; }
      } else if (!raf) {
        t0 = null; last = 0;
        raf = requestAnimationFrame(frame);
      }
    });

    gl.canvas.addEventListener("webglcontextlost", function (e) {
      e.preventDefault();
      if (raf) { cancelAnimationFrame(raf); raf = 0; }
      canvas.classList.remove("is-on");   // fall back to the JPEG
    });
  }

  if (document.readyState === "loading") {
    window.addEventListener("DOMContentLoaded", start);
  } else {
    start();
  }
})();
